"use client";

import React, { useState, useMemo } from "react";
import { 
  Calendar as CalendarIcon, 
  Users, 
  Clock, 
  CheckCircle2, 
  AlertCircle, 
  X, 
  ArrowRight, 
  FileText,
  PieChart
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [
  { date: "2026-01-01", name: "New Year's Day" },
  { date: "2026-01-14", name: "Sankranti" },
  { date: "2026-01-26", name: "Republic Day" } 
];

const TEAM_SCHEDULE = [
  { name: "Rahul V.", role: "Frontend Lead", dates: ["2026-01-12", "2026-01-15"], avatar: "bg-blue-100 text-blue-600" },
  { name: "Sarah J.", role: "Product Manager", dates: ["2026-01-20", "2026-01-22"], avatar: "bg-purple-100 text-purple-600" }
];

const BALANCES = { annual: 24, sick: 12, casual: 6 };

export default function EliteAbsencePortal() {
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [view, setView] = useState<"overview" | "request">("overview");
  const [formData, setFormData] = useState({ type: "annual", reason: "" });

  // --- LOGIC ENGINE ---
  const stats = useMemo(() => {
    if (!range.start || !range.end) return { days: 0, holidays: 0, weekends: 0 };
    let days = 0, holidays = 0, weekends = 0;
    let cur = new Date(range.start);
    let end = new Date(range.end);

    while (cur <= end) {
      const dateStr = cur.toISOString().split('T')[0];
      const day = cur.getDay();
      const isHoliday = HOLIDAYS.some(h => h.date === dateStr);

      if (isHoliday) holidays++;
      else if (day === 0 || day === 6) weekends++;
      else days++;
      
      cur.setDate(cur.getDate() + 1);
    }
    return { days, holidays, weekends };
  }, [range]);

  const handleDateSelect = (date: string) => {
    if (view === "request") return; // Lock calendar during form entry
    
    if (!range.start || (range.start && range.end)) {
      setRange({ start: date, end: "" });
    } else {
      const s = new Date(range.start);
      const e = new Date(date);
      if (e < s) setRange({ start: date, end: "" });
      else setRange({ ...range, end: date });
    }
  };

  const resetSelection = () => {
    setRange({ start: "", end: "" });
    setView("overview");
  };

  return (
    <div className="min-h-screen bg-[#F4F7FC] p-6 text-slate-800 font-sans">
      {/* HEADER: High density information */}
      <header className="mx-auto mb-6 max-w-[1400px] flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Time Off Management</h1>
          <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">Hyderabad Office • Engineering Team</p>
        </div>
        <div className="flex gap-4">
          <StatusBadge label="Team Availability" value="85%" color="bg-emerald-100 text-emerald-700" icon={<Users className="h-4 w-4" />} />
          <StatusBadge label="Pending Approvals" value="0" color="bg-blue-100 text-blue-700" icon={<Clock className="h-4 w-4" />} />
        </div>
      </header>

      <main className="mx-auto grid max-w-[1400px] grid-cols-12 gap-6 h-[calc(100vh-140px)]">
        
        {/* --- LEFT: CALENDAR (7 COLUMNS) --- */}
        <div className="col-span-12 lg:col-span-8 flex flex-col gap-6">
          <div className="flex-1 rounded-2xl border border-slate-200 bg-white p-8 shadow-sm relative overflow-hidden">
            
            {/* Calendar Header */}
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-3xl font-bold text-slate-800">January 2026</h2>
              <div className="flex gap-6 text-xs font-bold uppercase tracking-widest text-slate-400">
                <LegendItem color="bg-blue-600" label="Selection" />
                <LegendItem color="bg-orange-400" label="Holiday" />
                <LegendItem color="bg-slate-100 border" label="Weekend" />
              </div>
            </div>

            {/* The Grid */}
            <div className="grid grid-cols-7 h-full content-start">
              {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                <div key={d} className="mb-4 text-center text-xs font-bold text-slate-400 uppercase">{d}</div>
              ))}
              
              {/* Jan 1 is Thursday, so 3 empty slots for Mon-Wed */}
              {[null, null, null].map((_, i) => <div key={`empty-${i}`} />)}

              {Array.from({ length: 31 }).map((_, i) => {
                const day = i + 1;
                const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                const dateObj = new Date(2026, 0, day);
                const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
                const holiday = HOLIDAYS.find(h => h.date === dateStr);
                
                const isSelected = range.start === dateStr || range.end === dateStr;
                const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

                return (
                  <button
                    key={day}
                    onClick={() => handleDateSelect(dateStr)}
                    className={`relative h-20 w-full border-t border-r border-slate-50 transition-all text-left p-2 hover:bg-slate-50
                      ${isSelected ? "bg-blue-600 text-white shadow-lg z-10 scale-[1.05] rounded-xl border-none" : ""}
                      ${inRange ? "bg-blue-50 text-blue-700" : ""}
                      ${isWeekend && !isSelected && !inRange ? "bg-[#FAFAFA] text-slate-300" : ""}
                    `}
                  >
                    <span className="text-sm font-bold">{day}</span>
                    {holiday && !isSelected && !inRange && (
                       <span className="absolute bottom-2 left-2 right-2 block truncate text-[10px] font-bold text-orange-500 bg-orange-50 px-1 rounded">
                         {holiday.name}
                       </span>
                    )}
                  </button>
                );
              })}
            </div>

            {/* ACTION BAR (Floating) */}
            {range.start && range.end && view === "overview" && (
              <div className="absolute bottom-8 left-8 right-8 flex items-center justify-between rounded-xl bg-slate-900 p-4 text-white shadow-2xl animate-in slide-in-from-bottom-4">
                <div className="flex items-center gap-6">
                  <div>
                    <p className="text-[10px] font-bold uppercase text-slate-400">Start</p>
                    <p className="font-bold">{range.start}</p>
                  </div>
                  <ArrowRight className="h-5 w-5 text-slate-500" />
                  <div>
                    <p className="text-[10px] font-bold uppercase text-slate-400">End</p>
                    <p className="font-bold">{range.end}</p>
                  </div>
                  <div className="h-8 w-px bg-white/20 mx-2" />
                  <div>
                    <p className="text-[10px] font-bold uppercase text-slate-400">Net Days</p>
                    <p className="font-bold text-blue-400">{stats.days} Days</p>
                  </div>
                </div>
                <div className="flex gap-3">
                  <button onClick={resetSelection} className="px-4 py-2 text-xs font-bold uppercase tracking-wider text-slate-400 hover:text-white">Cancel</button>
                  <button onClick={() => setView("request")} className="rounded-lg bg-blue-600 px-6 py-2 text-xs font-bold uppercase tracking-wider text-white hover:bg-blue-500">
                    Continue
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* --- RIGHT: CONTEXT & FORM (5 COLUMNS) --- */}
        <div className="col-span-12 lg:col-span-4 flex flex-col gap-6">
          
          {/* STATE 1: OVERVIEW (Balances & Team) */}
          {view === "overview" && (
            <>
              {/* Balance Card */}
              <div className="rounded-2xl bg-white p-6 shadow-sm border border-slate-200">
                <div className="flex items-center justify-between mb-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2">
                    <PieChart className="h-4 w-4 text-slate-400" /> My Entitlement
                  </h3>
                  <span className="text-xs text-slate-400">Updated Today</span>
                </div>
                <div className="space-y-5">
                   <BalanceBar label="Annual Leave" total={24} used={6} color="bg-blue-500" />
                   <BalanceBar label="Sick Leave" total={12} used={2} color="bg-emerald-500" />
                   <BalanceBar label="Casual Leave" total={6} used={4} color="bg-amber-500" />
                </div>
              </div>

              {/* Team Conflict Card */}
              <div className="flex-1 rounded-2xl bg-white p-6 shadow-sm border border-slate-200">
                <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                  <Users className="h-4 w-4 text-slate-400" /> Team Conflicts
                </h3>
                {range.start ? (
                  <div className="space-y-4">
                     {/* Logic: If overlap, show warning. Static for now */}
                     <div className="rounded-lg bg-amber-50 p-3 flex gap-3 border border-amber-100">
                        <AlertCircle className="h-5 w-5 text-amber-600 shrink-0" />
                        <p className="text-xs text-amber-800 font-medium">
                          <strong>Note:</strong> 2 members have overlapping leave during this period. Approval may require manager review.
                        </p>
                     </div>
                     <div className="space-y-3">
                       {TEAM_SCHEDULE.map((m, i) => (
                         <div key={i} className="flex items-center justify-between p-3 rounded-xl bg-slate-50">
                            <div className="flex items-center gap-3">
                              <div className={`h-8 w-8 rounded-full flex items-center justify-center text-xs font-bold ${m.avatar}`}>
                                {m.name.charAt(0)}
                              </div>
                              <div>
                                <p className="text-xs font-bold text-slate-900">{m.name}</p>
                                <p className="text-[10px] text-slate-500">{m.role}</p>
                              </div>
                            </div>
                            <span className="text-[10px] font-bold bg-white px-2 py-1 rounded border border-slate-200">
                              Out {m.dates[0].slice(5)}
                            </span>
                         </div>
                       ))}
                     </div>
                  </div>
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-slate-300">
                     <CalendarIcon className="h-10 w-10 mb-2 opacity-20" />
                     <p className="text-xs font-medium">Select dates to check team overlap</p>
                  </div>
                )}
              </div>
            </>
          )}

          {/* STATE 2: REQUEST FORM (Replaces Sidebar) */}
          {view === "request" && (
            <div className="h-full rounded-2xl bg-white p-8 shadow-lg border border-slate-200 animate-in slide-in-from-right-4 flex flex-col">
               <div className="flex items-center justify-between mb-8">
                 <h2 className="text-xl font-bold">Finalize Request</h2>
                 <button onClick={resetSelection} className="text-slate-400 hover:text-slate-600">
                   <X className="h-5 w-5" />
                 </button>
               </div>

               <div className="space-y-6 flex-1">
                 {/* Summary Box */}
                 <div className="bg-slate-50 rounded-xl p-4 border border-slate-100">
                    <div className="grid grid-cols-2 gap-4 text-center">
                       <div>
                         <p className="text-[10px] font-bold uppercase text-slate-400">Total Duration</p>
                         <p className="text-2xl font-black text-slate-800">{stats.days + stats.weekends + stats.holidays}d</p>
                       </div>
                       <div>
                         <p className="text-[10px] font-bold uppercase text-slate-400">Deduction</p>
                         <p className="text-2xl font-black text-blue-600">{stats.days}d</p>
                       </div>
                    </div>
                    {stats.holidays > 0 && (
                      <p className="mt-3 text-[10px] text-center text-emerald-600 font-bold bg-emerald-50 py-1 rounded">
                        🎉 {stats.holidays} Public Holidays Saved
                      </p>
                    )}
                 </div>

                 {/* Inputs */}
                 <div className="space-y-4">
                    <div>
                      <label className="text-xs font-bold uppercase text-slate-500 mb-1 block">Leave Type</label>
                      <select 
                        className="w-full rounded-xl border border-slate-200 bg-white p-3 text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                        value={formData.type}
                        onChange={(e) => setFormData({...formData, type: e.target.value})}
                      >
                        <option value="annual">Annual Leave</option>
                        <option value="sick">Sick Leave</option>
                        <option value="casual">Casual Leave</option>
                      </select>
                    </div>
                    
                    <div>
                      <label className="text-xs font-bold uppercase text-slate-500 mb-1 block">Reason / Handoff</label>
                      <textarea 
                        className="w-full h-32 rounded-xl border border-slate-200 bg-white p-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none"
                        placeholder="Project X status is..."
                        value={formData.reason}
                        onChange={(e) => setFormData({...formData, reason: e.target.value})}
                      />
                    </div>

                    {formData.type === 'sick' && (
                       <div className="rounded-xl border-2 border-dashed border-slate-200 p-4 flex flex-col items-center justify-center text-slate-400 hover:bg-slate-50 hover:border-slate-300 cursor-pointer transition">
                          <FileText className="h-6 w-6 mb-2" />
                          <span className="text-xs font-bold">Attach Medical Cert</span>
                       </div>
                    )}
                 </div>
               </div>

               <div className="mt-auto pt-6 border-t border-slate-100">
                  <button className="w-full rounded-xl bg-slate-900 py-4 font-bold text-white hover:bg-black transition-all flex items-center justify-center gap-2">
                    Submit Request <ArrowRight className="h-4 w-4" />
                  </button>
               </div>
            </div>
          )}

        </div>
      </main>
    </div>
  );
}

// --- SUB COMPONENTS FOR CLEAN CODE ---
function LegendItem({ color, label }: { color: string, label: string }) {
  return (
    <div className="flex items-center gap-2">
      <span className={`h-2 w-2 rounded-full ${color}`} />
      <span>{label}</span>
    </div>
  )
}

function StatusBadge({ label, value, color, icon }: any) {
  return (
    <div className={`flex items-center gap-3 rounded-full px-4 py-2 ${color} bg-opacity-20`}>
      {icon}
      <div className="flex flex-col leading-none">
        <span className="text-[9px] font-bold uppercase opacity-70">{label}</span>
        <span className="text-sm font-bold">{value}</span>
      </div>
    </div>
  )
}

function BalanceBar({ label, total, used, color }: any) {
  const remaining = total - used;
  const pct = (remaining / total) * 100;
  return (
    <div>
      <div className="flex justify-between text-xs font-bold mb-2">
        <span className="text-slate-600">{label}</span>
        <span className="text-slate-900">{remaining} Days</span>
      </div>
      <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
        <div className={`h-full ${color}`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  )
}